// El RPC público de Fuji acepta hasta 100 bloques por pedido de eth_getLogs (si pedís más,
// responde «block range too large»). Por eso partimos el rango en tramos de 100: cada tramo es un
// ítem y el HTTP Request siguiente hace un pedido por ítem.
const config = $('Qué buscar').first().json;
const ultimo = BigInt($input.first().json.result);

const POR_PEDIDO = 100n; // límite del RPC público
const TRAMOS_MAXIMOS = 10n; // como mucho 10 pedidos (1000 bloques) por ejecución, para cuidar el RPC
const tope = POR_PEDIDO * TRAMOS_MAXIMOS;
const menor = (a, b) => (a < b ? a : b);

let desde;
let hasta;
const desdeBloque = String(config.desdeBloque ?? '').trim();
if (desdeBloque) {
  // Desde un bloque fijo (por ejemplo, el del despliegue de tu contrato) hacia adelante.
  desde = BigInt(desdeBloque);
  if (desde > ultimo) throw new Error(`desdeBloque (${desde}) es mayor que el último bloque de Fuji (${ultimo}).`);
  hasta = menor(desde + tope - 1n, ultimo);
} else {
  // Los últimos N bloques.
  const n = menor(BigInt(config.bloquesHaciaAtras || 100), tope);
  hasta = ultimo;
  desde = ultimo - n + 1n;
}

// El filtro de eth_getLogs: rango, topics (topic0 = qué evento) y, si lo pusiste, el contrato.
const topic0 = String(config.topic0 ?? '').trim().toLowerCase();
const contrato = String(config.contrato ?? '').trim().toLowerCase();
const tramos = [];
for (let a = desde; a <= hasta; a += POR_PEDIDO) {
  const b = menor(a + POR_PEDIDO - 1n, hasta);
  const filtro = { fromBlock: '0x' + a.toString(16), toBlock: '0x' + b.toString(16) };
  if (topic0) filtro.topics = [topic0];
  if (contrato) filtro.address = contrato;
  tramos.push({ json: { desdeBloque: Number(a), hastaBloque: Number(b), filtro } });
}
return tramos;

// Decodifica cada evento (log). Un log trae:
//   topics[0]  qué evento es: el keccak256 de su firma, por ejemplo Transfer(address,address,uint256)
//   topics[1+] los parámetros «indexed», cada uno en 32 bytes
//   data       el resto de los parámetros, codificados con la ABI
const config = $('Qué buscar').first().json;
const tramos = $('Partir en tramos de 100 bloques').all();

const TRANSFER = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef';
// ProyectoRegistrado(address,string,string,uint256), del contrato de ejemplo en avalanche/contratos
const PROYECTO_REGISTRADO = '0xa349a1d38906b94dcd1cbd81cc94738a389a4deaf16ae3d301bc1617cc04df77';

const palabra = (data, i) => '0x' + data.slice(2 + i * 64, 2 + (i + 1) * 64); // la palabra i de 32 bytes
const direccion = (topic) => '0x' + topic.slice(26); // una dirección ocupa los últimos 20 bytes
function texto(data, i) {
  // Un string de la ABI: en la palabra i está dónde empieza (en bytes); ahí, su largo y después sus bytes.
  const d = data.slice(2);
  const inicio = Number(BigInt(palabra(data, i))) * 2;
  const largo = Number(BigInt('0x' + d.slice(inicio, inicio + 64)));
  return Buffer.from(d.slice(inicio + 64, inicio + 64 + largo * 2), 'hex').toString('utf8');
}
function conDecimales(valor, decimales) {
  if (!decimales) return valor.toString();
  const base = 10n ** BigInt(decimales);
  const resto = (valor % base).toString().padStart(decimales, '0').replace(/0+$/, '');
  return resto ? `${valor / base}.${resto}` : `${valor / base}`;
}
const decimales = String(config.decimales ?? '').trim() === '' ? null : Number(config.decimales);
const contrato = String(config.contrato ?? '').trim().toLowerCase();

const eventos = [];
$input.all().forEach((item, i) => {
  const tramo = tramos[i].json;
  if (item.json.error) {
    throw new Error(`eth_getLogs falló en los bloques ${tramo.desdeBloque} a ${tramo.hastaBloque}: ${item.json.error.message ?? JSON.stringify(item.json.error)}`);
  }
  for (const log of item.json.result || []) {
    const e = {
      bloque: Number(BigInt(log.blockNumber)),
      transaccion: log.transactionHash,
      contrato: log.address,
    };
    const t0 = log.topics[0];
    if (t0 === TRANSFER && log.topics.length === 3) {
      // ERC-20: de y para son indexed (topics 1 y 2); el monto viaja en data.
      const valor = BigInt(palabra(log.data, 0));
      Object.assign(e, { evento: 'Transfer (ERC-20)', de: direccion(log.topics[1]), para: direccion(log.topics[2]), valorCrudo: valor.toString() });
      if (decimales !== null && contrato && log.address.toLowerCase() === contrato) e.valor = conDecimales(valor, decimales);
    } else if (t0 === TRANSFER && log.topics.length === 4) {
      // ERC-721 (NFT): la misma firma, pero el tercer parámetro (tokenId) también es indexed.
      Object.assign(e, { evento: 'Transfer (ERC-721)', de: direccion(log.topics[1]), para: direccion(log.topics[2]), tokenId: BigInt(log.topics[3]).toString() });
    } else if (t0 === PROYECTO_REGISTRADO) {
      // autora es indexed (topic 1). En data: dónde empieza nombre, dónde empieza enlace y cuando.
      const cuando = Number(BigInt(palabra(log.data, 2)));
      Object.assign(e, {
        evento: 'ProyectoRegistrado',
        autora: direccion(log.topics[1]),
        nombre: texto(log.data, 0),
        enlace: texto(log.data, 1),
        cuando: DateTime.fromSeconds(cuando, { zone: 'America/La_Paz' }).toFormat('dd/MM/yyyy HH:mm:ss'),
      });
    } else {
      // Un evento que este nodo no conoce: lo dejamos crudo para que lo decodifiques vos.
      Object.assign(e, { evento: 'otro', topics: log.topics, data: log.data });
    }
    e.explorador = `https://build.avax.network/explorer/fuji/c-chain/tx/${log.transactionHash}`;
    eventos.push(e);
  }
});

if (!eventos.length) {
  const primero = tramos[0].json.desdeBloque;
  const ultimo = tramos[tramos.length - 1].json.hastaBloque;
  return [{ json: { eventos: 0, mensaje: `No hubo eventos con ese filtro entre los bloques ${primero} y ${ultimo}. Probá con más bloques, otro contrato o sin contrato.` } }];
}
return eventos.map((json) => ({ json }));
